def compute_bjacs_from_bjac(bjac, rho_nodes=None, s_nodes=None):
    """Compute TERPSICHORE ``BJACS = d ln(BJAC) / ds`` on radial nodes.

    ``BJAC`` is the coordinate Jacobian, which is negative in TERPSICHORE's
    left-handed frame.  The logarithmic derivative is invariant under a global
    sign, so ``|BJAC|`` is used; only a Jacobian that changes sign (a degenerate
    or wrongly oriented mapping) is rejected.
    """

    arr = np.asarray(bjac, dtype=float)
    if s_nodes is None:
        if rho_nodes is None:
            raise TerpsichoreMigrationNotImplementedError(
                "BJACS derivation needs either s_nodes or rho_nodes."
            )
        s_nodes = np.asarray(rho_nodes, dtype=float) ** 2
    else:
        s_nodes = np.asarray(s_nodes, dtype=float)
    if s_nodes.size < 2:
        raise TerpsichoreMigrationNotImplementedError(
            "BJACS derivation needs at least two radial nodes."
        )
    if np.any(arr == 0) or not (np.all(arr > 0) or np.all(arr < 0)):
        raise ValueError("BJACS derivation requires a nonzero constant-sign bjac.")
    arr = np.abs(arr)

