    equilibrium_data,
    mode_table,
    radial_grid=None,
    *,
    geometry=None,
    boozer=None,
    trig_table=None,
    modelk=0,
    strict=True,
    transform_options=None,
    fixed_boundary=True,
    igreen=0,
    cospar=1.0,
    cospr2=1.0,
    dtdp=None,
):
